'use strict';
let intakePendingText='';
// Conservative extraction of explicit names, durations and labeled directions.
// No model inference: ambiguous or missing values stay empty for human review.
function intakeNormalize(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function intakeMention(text,name){const term=intakeNormalize(name).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return term.length>2&&new RegExp('(^|[^a-z0-9])'+term+'($|[^a-z0-9])').test(text)}
function intakeNumber(value){const text=intakeNormalize(value).trim();if(/^\d+(?:[.,]\d+)?$/.test(text))return Number(text.replace(',','.'));const numbers={um:1,uma:1,dois:2,duas:2,tres:3,quatro:4,cinco:5,seis:6,sete:7,oito:8,nove:9,dez:10,onze:11,doze:12,treze:13,quatorze:14,catorze:14,quinze:15,dezesseis:16,dezessete:17,dezoito:18,dezenove:19,vinte:20,trinta:30,quarenta:40,cinquenta:50,sessenta:60,setenta:70,oitenta:80,noventa:90,cento:100,cem:100,duzentos:200,trezentos:300,quatrocentos:400,quinhentos:500,seiscentos:600,setecentos:700,oitocentos:800,novecentos:900,meia:.5};if(/\bmil\b/.test(text)){const [before,after,...rest]=text.split(/\s*\bmil\b\s*/);if(rest.length)return NaN;return (before?intakeNumber(before):1)*1000+(after?intakeNumber(after.replace(/^e\s+/,'')):0)}const parts=text.split(/\s+e\s+/);return parts.every(p=>numbers[p])?parts.reduce((sum,p)=>sum+numbers[p],0):NaN}
function intakeDraft(text){const normalized=intakeNormalize(text),warnings=[];
 const candidates=activeProjects().filter(p=>{let host='';try{host=new URL(p.url).hostname.replace(/^www\./,'')}catch{}return intakeMention(normalized,p.name)||(host&&intakeMention(normalized,host))});
 const pr=candidates.length===1?candidates[0]:null;if(!pr)warnings.push(candidates.length>1?'Você citou mais de um projeto. Escolha o desta sprint.':'Escolha o projeto deste pedido.');
 const directors=studio().people.filter(p=>p.kind!=='advisor'&&p.status==='Aprovado'&&(/diret/i.test(p.role)||studio().projects.some(pr=>pr.directorId===p.id)));
 const named=directors.filter(p=>intakeMention(normalized,p.name)||intakeMention(normalized,p.name.split(' ')[0]));
 let lead=named.length===1?named[0]:null;let inherited=false;
 if(!named.length&&pr?.directorId&&!/diretora?\s+(?:chamada\s+)?[a-z]+/.test(normalized)){const assigned=person(pr.directorId);if(assigned?.status==='Aprovado'){lead=assigned;inherited=true}}
 if(lead&&pr&&!personOnProject(lead,pr.id)){warnings.push('A diretora citada não atende este projeto. Escolha outro perfil.');lead=null}
 if(!lead)warnings.push(named.length>1?'Mais de uma diretora foi citada. Escolha a responsável.':'Escolha a diretora responsável.');
 const wordNumbers='um|uma|dois|duas|tres|quatro|cinco|seis|sete|oito|nove|dez|onze|doze|treze|quatorze|catorze|quinze|dezesseis|dezessete|dezoito|dezenove|vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa|cem|cento|duzentos|trezentos|quatrocentos|quinhentos|seiscentos|setecentos|oitocentos|novecentos|mil|meia';
 const numbers='(?:\\d+(?:[.,]\\d+)?|(?:'+wordNumbers+')(?:\\s+(?:e\\s+)?(?:'+wordNumbers+'))*)';
 const all=[...normalized.matchAll(new RegExp('\\b('+numbers+')\\s*(minutos?|min|horas?|dias?)\\b','g'))];
 const explicit=all.filter(m=>/(?:prazo(?:\s+de)?|em|ate|tem|dou|durante)\s*$/.test(normalized.slice(Math.max(0,m.index-20),m.index)));
 const times=all.length>1&&(/\bou\b/.test(normalized)||/\bhoras?\s+e\b/.test(normalized))?all:explicit.length?explicit:all;let minutes='';if(times.length===1){const m=times[0],amount=intakeNumber(m[1]),factor=m[2].startsWith('hora')?60:m[2].startsWith('dia')?1440:1;minutes=amount*factor;if(m[2].startsWith('hora')&&/^\s+e\s+meia\b/.test(normalized.slice(m.index+m[0].length)))minutes+=30;if(!Number.isInteger(minutes)||minutes<1||minutes>525600)minutes=''}
 if(!minutes)warnings.push(times.length>1?'Há mais de uma duração na fala. Confirme o prazo total.':'Defina o prazo total da sprint.');
 const labeled=label=>{const match=text.match(new RegExp('(?:^|[.;\\n])\\s*(?:'+label+')\\s*:\\s*([^;\\n]+)','i'));return match?match[1].trim():''};
 const strategy={kind:'editorial',audience:labeled('público|publico'),offer:labeled('oferta'),channel:labeled('canal'),action:labeled('ação|acao'),metric:labeled('meta|métrica|metrica'),sources:labeled('fontes'),examples:labeled('referências|referencias'),constraints:labeled('limites|restrições|restricoes')};
 return {project:pr?.id||'',director:lead?.id||'',brief:text.trim(),title:'',format:labeled('entrega|formato'),minutes,strategy,warnings,inherited};
}
function openIntake(){const form=studioForm('Conte o desafio uma vez.','Recepção · pedido à diretora',`<p class="form-context">Fale naturalmente: qual projeto, o que você espera receber, quem deve dirigir e em quanto tempo. O pedido completo será preservado. Você confere os campos antes de registrar.</p>`+field('intake','Seu briefing — por voz ou por escrito',intakePendingText,'textarea','Ex.: Para o Paraibão, quero uma matéria sobre IA. Marina dirige e tem trinta minutos. Tom crítico, fontes verificadas e uma chamada para a newsletter.',true),fd=>{const text=String(fd.get('intake')||'').trim();if(!text)return {error:'Grave ou escreva seu pedido.'};intakePendingText=text;const draft=intakeDraft(text);setTimeout(()=>taskForm(undefined,draft.project,draft),0);return {action:'Preparou pedido para revisão'}},'<small>Próximo passo: revisar o pedido.<br>Nenhuma sprint começa automaticamente.</small>');form.addEventListener('voice:ready',e=>{if(e.target.name==='intake'){intakePendingText=e.target.value;const draft=intakeDraft(e.target.value);taskForm(undefined,draft.project,draft)}});const submit=document.querySelector('#studio-form [type="submit"]');if(submit)submit.textContent='Revisar e preencher pedido'}
document.addEventListener('click',e=>{if(e.target.closest('[data-intake]'))openIntake()});
